      if (result.applied && result.amount > 0) {
        splashHits.push({ id, amount: result.amount, at: { x: pos.x | 0, y: pos.y | 0 } });
      }
    }
  }

  world.emit('healed', { id: actor, amount: actualHeal });
  world.emit('spell:flash_heal', {
    actor,
    targetId: actor,
    at: { x: apos.x, y: apos.y },
    amount: actualHeal,
    spellLevel,
    splashHits,
  });
};

